// The codex: one entry per palette item, analysis and concept, in reading order.
// This is the metadata only (title, search terms, links); the prose lives in the
// Markdown entries and the parameter tables are generated by paramTable.ts.
import type { ModelKind, PartType } from "@nodal/schema";
import { LABEL_SYMBOL, SYMBOLS } from "../symbols/catalog";

export type EntryKind = "part" | "analysis" | "concept";

export interface CodexEntryMeta {
  id: string;
  kind: EntryKind;
  title: string;
  aliases: readonly string[];
  keywords: readonly string[];
  item?: PartType | "label";
  model?: ModelKind;
  analysis?: "op" | "dc" | "ac" | "tran";
  /** An `EXAMPLES` id that contains this part or shows this analysis. */
  tryIt?: string;
  related: readonly string[];
}

type PartInit = Omit<CodexEntryMeta, "id" | "kind" | "title" | "item" | "keywords"> & {
  keywords?: readonly string[];
};

function part(item: PartType | "label", init: PartInit): CodexEntryMeta {
  const title = item === "label" ? LABEL_SYMBOL.label : SYMBOLS[item].label;
  return { id: item, kind: "part", title, item, keywords: [], ...init };
}

function entry(
  kind: "analysis" | "concept",
  id: string,
  title: string,
  init: Omit<CodexEntryMeta, "id" | "kind" | "title" | "keywords"> & {
    keywords?: readonly string[];
  },
): CodexEntryMeta {
  return { id, kind, title, keywords: [], ...init };
}

