const BY_ITEM = new Map(CODEX.flatMap((e) => (e.item === undefined ? [] : [[e.item, e] as const])));

/** The part entry for a palette item. */
export function entryForItem(item: PartType | "label"): CodexEntryMeta {
  const found = BY_ITEM.get(item);
  if (found === undefined) throw new Error(`no codex entry for ${item}`);
  return found;
}
